#!/usr/bin/env node
// Task-local replacement for the email-api skill's email-contacts.js helper,
// which could not run because its 'minimist' dependency is not installed.
// Makes the same authenticated GET request to the /contacts endpoint.

const fs = require('fs');

const creds = JSON.parse(fs.readFileSync('email_credentials.json', 'utf8'));
const apiKey = creds.account.api_key;
const userEmail = creds.account.email;

// Script default in email-contacts.js, and default in the skill manifest.
const CANDIDATES = [
  process.env.EMAIL_API_BASE_URL,
  'https://agenskill.onrender.com',
  'https://agenskill-api.onrender.com'
].filter(Boolean);

(async () => {
  let lastError = null;
  for (const base of [...new Set(CANDIDATES)]) {
    try {
      const res = await fetch(`${base}/contacts`, {
        headers: { 'X-API-Key': apiKey, 'X-User-Email': userEmail }
      });
      const text = await res.text();
      let data;
      try { data = JSON.parse(text); } catch { data = null; }
      if (!res.ok) {
        lastError = new Error(`HTTP ${res.status} from ${base}: ${text.slice(0, 300)}`);
        continue;
      }
      const contacts = Array.isArray(data && data.contacts) ? data.contacts : [];
      console.log(JSON.stringify({ success: true, url: base, count: contacts.length, contacts }, null, 2));
      return;
    } catch (err) {
      lastError = err;
    }
  }
  console.error(JSON.stringify({ success: false, error: String(lastError && lastError.message || lastError) }, null, 2));
  process.exit(1);
})();
